package convertion

import (
	iam_v1 "github.com/linjunhao1997/idl/pb/iam"
	"math"
)

func GetLimitAndOffset(page *iam_v1.Page) (limit, offset int) {
	if page == nil {
		return 10, 0
	}
	if page.PageSize < 0 {
		return 0, 0
	}
	if page.PageSize > 100 {
		return 100, 0
	}
	if page.CurrentPage < 1 {
		return 0, 0
	}

	return int(page.PageSize), int(page.CurrentPage-1) * int(page.PageSize)
}

func GetPageResult(page *iam_v1.Page, total int64) *iam_v1.PageResult {
	var currentPage, pageSize int
	if page == nil {
		page = &iam_v1.Page{
			CurrentPage: 1,
			PageSize:    10,
		}
	}

	if page.CurrentPage < 0 {
		currentPage = 1
	}
	if page.PageSize < 0 {
		pageSize = 10
	} else if page.PageSize > 100 {
		pageSize = 100
	}
	// 求总页数
	totalPages := int(math.Ceil(float64(total) / float64(pageSize)))

	return &iam_v1.PageResult{
		Total:       total,
		CurrentPage: int64(currentPage),
		PageSize:    int64(pageSize),
		TotalPages:  int64(totalPages),
	}
}
